/* Patient › New Request: same form as the staff "Create Request" with the patient pre-selected. Health Letter requests pick a letter from the
   template library (Settings › Templates › Health Letters); free letters submit straight away, paid letters go through secure payment first.
   Every request also lands in the clinic's EHR Inbox. */
(function () {
  const { esc, acts, ins, chs } = App; const PT = App.PT, S = App.S;
  const keep = () => { const y = scrollY; App.render(); scrollTo(0, y); };
  const meta = { key: 'me-req', icon: 'ri-heart-add-line', title: 'My Requests' };
  const ME = 'p0', money = n => '£' + Number(n).toFixed(2);
  const CATS = { Appointment: ['New appointment request', 'Follow-up request'], Prescription: ['Repeat prescription', 'Medication query'], 'Health Letter': null, Other: ['General enquiry', 'Results query', 'Something else'] };
  const DUR = ['Not sure', '1 week', '2 weeks', '1 month', '3 months', '6 months', '12 months', 'Ongoing'];
  const FOR = ['Employer', 'School or university', 'Airline or travel provider', 'Gym or sports club', 'Insurance company', 'Other'];
  const letters = () => (S.letterTemplates || []).filter(l => l.status === 'Active');
  const N = App.ui.meNew = { cat: '', type: '', letter: '', desc: '', dur: '', from: '', forWho: '', needBy: '', files: [], err: [] };
  const L = () => letters().find(l => l.id === N.letter);
  const reset = () => Object.assign(N, { cat: '', type: '', letter: '', desc: '', dur: '', from: '', forWho: '', needBy: '', files: [], err: [] });
  const pid = () => { const p = PT.pat(ME); return 'PT-' + (3000 + (S.patients.indexOf(p) + 1) * 127 % 1000); };
  const err = k => N.err.includes(k) ? ' err' : '';

  App.meNewReq = () => { const p = PT.pat(ME), l = L(), cat = N.cat;
    const pchip = x => x.paid ? `<span class="ct-type t-orange">Paid · ${money(x.price)}</span>` : '<span class="ct-type t-green">Free</span>';
    const typeField = cat === 'Health Letter' ? `<button type="button" class="field select mr-lpick ${err('letter')}" data-act="mr-lpick" data-menu-anchor aria-haspopup="listbox" aria-label="Type of health letter"><label>Type of Health Letter <b>*</b></label>${l ? `<span class="grow mr-lsel"><span>${esc(l.name)}</span>${pchip(l)}</span>` : '<span class="grow caption">Choose a letter</span>'}<i class="ri-arrow-down-s-fill"></i></button>` : App.field('Request Type', `<select data-ch="mr" data-k="type" ${cat ? '' : 'disabled'}><option value="" disabled ${N.type ? '' : 'selected'}>${cat ? 'Choose a type' : 'Choose a category first'}</option>${(CATS[cat] || []).map(t => `<option ${N.type === t ? 'selected' : ''}>${t}</option>`).join('')}</select>`, { req: true, cls: 'select' + err('type') });
    const letterBlock = cat !== 'Health Letter' ? '' : `<div class="mr-opt"><div class="row between"><b>A few more details</b><span class="caption">Optional — helps the clinician write it</span></div><div class="g2" style="gap:12px">${App.field('How long do you need it for?', `<select data-ch="mr" data-k="dur"><option value="" ${N.dur ? '' : 'selected'}>Choose a period</option>${DUR.map(d => `<option ${N.dur === d ? 'selected' : ''}>${d}</option>`).join('')}</select>`, { cls: 'select' })}${App.field('Starting from', `<input type="date" data-ch="mr" data-k="from" value="${N.from}" min="2026-10-01">`)}${App.field('Who is the letter for?', `<select data-ch="mr" data-k="forWho"><option value="" ${N.forWho ? '' : 'selected'}>Choose one</option>${FOR.map(d => `<option ${N.forWho === d ? 'selected' : ''}>${d}</option>`).join('')}</select>`, { cls: 'select' })}${App.field('Date you need it by', `<input type="date" data-ch="mr" data-k="needBy" value="${N.needBy}" min="2026-10-23">`)}</div></div>`;
    const cta = l && l.paid ? `<button class="btn primary lg" data-act="mr-go"><i class="ri-bank-card-line"></i>Continue to Payment · ${money(l.price)}</button>` : '<button class="btn primary lg" data-act="mr-go">Submit Request</button>';
    return `<nav class="crumbs"><a href="#/me/requests">My Requests</a><span>/</span><span class="cur">New Request</span></nav><div class="pt-bar"><div class="me-head"><h1>New Request</h1><p>Tell the clinic what you need. A clinician reviews every request.</p></div><span class="grow"></span><a class="btn outlined lg pt-dark" href="#/me/requests" data-act="mr-cancel">Cancel</a>${cta}</div>
      <section class="card card-pad stack g16"><form id="mr-form" class="stack g16" onsubmit="return false">
        <div class="field select mr-me"><label>Patient</label><span class="row g8"><span class="av sm">${App.initials(PT.name(p))}</span><b class="fw5">${esc(PT.name(p))}</b><small class="caption">${pid()} · DOB ${PT.dmy(p.dob)}</small></span><i class="ri-lock-line" title="This is you"></i></div>
        <div class="g2" style="gap:16px">${App.field('Request Category', `<select data-ch="mr" data-k="cat"><option value="" disabled ${cat ? '' : 'selected'}>Choose a category</option>${Object.keys(CATS).map(k => `<option ${cat === k ? 'selected' : ''}>${k}</option>`).join('')}</select>`, { req: true, cls: 'select' + err('cat') })}${typeField}</div>
        ${letterBlock}
        ${l ? (l.paid ? `<div class="pa-bar orange"><i class="ri-money-pound-circle-line"></i><span><b>${esc(l.name)}</b> costs <b>${money(l.price)}</b>. You’ll pay securely by card before your request is sent to the clinic.</span></div>` : `<div class="pa-bar green"><i class="ri-gift-line"></i><span><b>${esc(l.name)}</b> is free. Submit your request and the clinic will prepare it.</span></div>`) : ''}
        ${App.field(cat === 'Health Letter' ? 'Anything the clinician should include? (optional)' : 'Request Details', `<textarea rows="3" data-in="mr" data-k="desc" maxlength="1000" placeholder="${cat === 'Health Letter' ? 'e.g. Reason for the letter, dates you were unwell, or wording your employer asked for.' : 'What do you need? Include anything that helps the team, like symptoms and how long you’ve had them.'}">${esc(N.desc)}</textarea>`, { req: cat === 'Other', cls: 'multi' + err('desc') })}
        <label class="ib-drop" id="mr-drop"><input type="file" hidden multiple accept=".pdf,.jpg,.jpeg,.png" data-ch="mr-files"><i class="ri-file-copy-2-line"></i><span>Drag a document here or <b>browse</b></span><small>PDF, JPG or PNG · max 10 MB</small></label>
        ${N.files.map((x, i) => `<div class="ib-file"><i class="ri-file-pdf-2-line"></i><div class="grow"><b>${esc(x.name)}</b><small>${x.size} · uploaded just now</small></div><button type="button" class="icon-btn s20" data-act="mr-fdel" data-i="${i}" aria-label="Remove ${esc(x.name)}"><i class="ri-close-line"></i></button></div>`).join('')}</form></section>`; };
  chs['mr'] = el => { const k = el.dataset.k; N[k] = el.value; if (k === 'cat') { N.type = ''; N.letter = ''; } N.err = N.err.filter(x => x !== k); keep(); };
  ins['mr'] = el => { N[el.dataset.k] = el.value; el.closest('.field').classList.remove('err'); };
  acts['mr-lpick'] = el => { const L2 = letters(), rows = q => L2.filter(x => !q || (x.name + x.cat).toLowerCase().includes(q.toLowerCase())).map(x => `<button data-pick="${x.id}" class="mr-lrow ${N.letter === x.id ? 'on' : ''}" role="option" aria-selected="${N.letter === x.id}"><span class="grow"><b>${esc(x.name)}</b><small>${esc(x.cat)}</small></span>${x.paid ? `<span class="ct-type t-orange">Paid · ${money(x.price)}</span>` : '<span class="ct-type t-green">Free</span>'}</button>`).join('') || '<div class="caption" style="padding:12px">No letters match.</div>';
    App.menu(el, `<div class="pt-staff-menu"><div class="field sm"><input placeholder="Search letters…" aria-label="Search letters"><span class="adorn"><i class="ri-search-line"></i></span></div><div class="pt-staff-list" role="listbox">${rows('')}</div></div>`, v => { N.letter = v; N.err = N.err.filter(x => x !== 'letter'); keep(); }, { width: el.offsetWidth, alignLeft: true, onSearch: (q, m) => { m.querySelector('.pt-staff-list').innerHTML = rows(q); } }); };
  chs['mr-letter'] = el => { N.letter = el.value; N.err = N.err.filter(x => x !== 'letter'); keep(); };
  const addFiles = list => { [...list].forEach(x => { if (!/\.(pdf|jpe?g|png)$/i.test(x.name)) return App.snack(`“${x.name}” isn’t a PDF, JPG or PNG.`, 'error'); if (x.size > 10e6) return App.snack(`“${x.name}” is over 10 MB.`, 'error'); N.files.push({ name: x.name, size: Math.max(1, Math.round(x.size / 1024)) + ' KB' }); }); keep(); };
  chs['mr-files'] = el => addFiles(el.files); acts['mr-fdel'] = el => { N.files.splice(+el.dataset.i, 1); keep(); };
  document.addEventListener('dragover', e => { const d = e.target.closest && e.target.closest('#mr-drop'); if (d) { e.preventDefault(); d.classList.add('over'); } });
  document.addEventListener('dragleave', e => { const d = e.target.closest && e.target.closest('#mr-drop'); if (d) d.classList.remove('over'); });
  document.addEventListener('drop', e => { const d = e.target.closest && e.target.closest('#mr-drop'); if (d) { e.preventDefault(); addFiles(e.dataTransfer.files); } });
  acts['mr-cancel'] = () => reset();

  const valid = () => { N.err = []; if (!N.cat) N.err.push('cat'); else if (N.cat === 'Health Letter') { if (!N.letter) N.err.push('letter'); } else if (!N.type) N.err.push('type'); if (N.cat === 'Other' && !N.desc.trim()) N.err.push('desc'); return !N.err.length; };
  acts['mr-go'] = () => { if (!valid()) { keep(); return App.snack(N.cat === 'Health Letter' && !N.letter ? 'Choose the type of health letter you need.' : 'Fill in the highlighted fields.', 'error'); }
    const l = L(); if (l && l.paid) return App.go('#/me/requests/new/pay'); submit(); };

  /* create the patient request + the clinic's inbox case (+ the paid invoice) */
  const stamp = () => '2026-10-23 ' + new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
  const submit = inv => { const l = L(), R = S.myReqs, at = stamp(), letter = N.cat === 'Health Letter', title = letter ? l.name : N.type, id = 'r' + (R.length + 1) + Date.now() % 1000;
    const info = letter ? { name: l.name, cat: l.cat, paid: !!l.paid, price: l.price, inv: inv || '', dur: N.dur, from: N.from, forWho: N.forWho, needBy: N.needBy } : null;
    R.unshift({ id, title, type: letter ? 'Health Letter' : N.type, status: 'Pending', at, prac: 'To be assigned', form: letter ? 'letter' : 'basic', assigned: 'Unassigned', items: [], chat: [], mhNotes: [], desc: N.desc.trim(), files: N.files.map(f => f.name), letter: info,
      log: [['Request submitted', at, 'Ahmed Raza', 'grey'], ...(inv ? [[`Payment of ${money(l.price)} received (${inv})`, at, 'Ahmed Raza', 'green']] : [])] });
    if (S.cases) { const extra = info ? [info.dur && `Needed for: ${info.dur}`, info.from && `From: ${info.from.split('-').reverse().join('/')}`, info.forWho && `For: ${info.forWho}`, info.needBy && `Needed by: ${info.needBy.split('-').reverse().join('/')}`].filter(Boolean).join(' · ') : '';
      S.cases.unshift({ id: 'IN-' + (1201 + S.cases.length), reqId: id, letterReq: info, title, cat: letter ? 'Letter' : N.cat, pid: ME, who: null, match: 'linked', status: 'Under Review', type: letter ? 'Health letter — ' + l.name : N.type, source: 'Platform', dept: N.cat === 'Prescription' ? 'Pharmacists' : 'GP’s', assigned: 'Sofia Sadiq', autoBy: 'Sofia Sadiq', closed: false, appt: null, submitted: '2026-10-23', updated: 'just now', practitioner: 'To be assigned', candIdx: 0,
        desc: [N.desc.trim() || (letter ? `Patient requested “${l.name}”.` : 'Submitted from the patient portal.'), extra, info && info.paid ? `Paid ${money(l.price)} online (${inv}).` : info ? 'Free letter.' : ''].filter(Boolean).join('\n'), docs: N.files.map(f => f.name), notes: [], chat: [], reqDocs: [], logs: [['Request submitted from patient portal', at.split(' ').reverse().join(', '), 'Ahmed Raza'], ['Auto-assigned to Sofia Sadiq', at, 'System']] }); }
    reset(); App.go('#/me/requests/' + id); App.snack(inv ? 'Payment received and your request has been sent to the clinic.' : 'Request submitted. You’ll be notified when a clinician reviews it.'); };
  /* demo: two health-letter requests on Ahmed's list — one issued (closed), one paid and with the clinic (also in the EHR Inbox) */
  (() => { const R = S.myReqs; if (!R || R.some(r => r.form === 'letter')) return; const T = n => (S.letterTemplates || []).find(x => x.name === n); const fit = T('Fit Note — Statement of Fitness for Work'), fly = T('Fit to Fly Certificate'); if (!fit || !fly) return;
    const mk = (id, l, at, status, x) => ({ id, title: l.name, type: 'Health Letter', status, at, prac: x.prac || 'To be assigned', form: 'letter', assigned: x.prac || 'Sofia Sadiq', items: [], chat: [], mhNotes: [], desc: x.desc, files: x.files || [], letter: Object.assign({ name: l.name, cat: l.cat, paid: !!l.paid, price: l.price, inv: x.inv || '' }, x.info), log: x.log });
    const flyInv = 'HC-5290'; if (S.inv2 && !S.inv2.some(v => v.id === flyInv)) S.inv2.push({ id: flyInv, pid: ME, svc: fly.name, kind: 'Service', amt: +fly.price, status: 'Payment Complete', issued: new Date(2026, 9, 22, 9, 58), appt: new Date(2026, 9, 22, 9, 58), ref: 'Health letter', clin: 'LeafEase Clinic', method: 'Card', pays: [{ amt: +fly.price, method: 'Card', at: new Date(2026, 9, 22, 9, 58) }], log: [['Payment successfully made', new Date(2026, 9, 22, 9, 58), '']] });
    const a = mk('rhl2', fly, '2026-10-22 09:58', 'Under Clinical Review', { inv: flyInv, desc: 'I’m flying to Spain on 3 December and the airline needs a fit-to-fly letter after my knee surgery.', files: ['discharge-summary.pdf'], info: { dur: '1 month', from: '2026-12-03', forWho: 'Airline or travel provider', needBy: '2026-11-25' },
      log: [['Request submitted', '2026-10-22 09:55', 'Ahmed Raza', 'grey'], ['Payment of £' + Number(fly.price).toFixed(2) + ' received (' + flyInv + ')', '2026-10-22 09:58', 'Ahmed Raza', 'green'], ['Reviewed by GP', '2026-10-22 11:10', 'Dr. Sarah Mitchell', 'blue']] });
    const b = mk('rhl1', fit, '2026-10-20 10:15', 'Closed', { prac: 'Dr. Sarah Mitchell', desc: 'Off work since Monday with lower back pain — my employer needs a fit note.', info: { dur: '2 weeks', from: '2026-10-21', forWho: 'Employer', needBy: '' }, issued: 'HL-2041',
      log: [['Request submitted', '2026-10-20 10:15', 'Ahmed Raza', 'grey'], ['Reviewed by GP', '2026-10-20 14:02', 'Dr. Sarah Mitchell', 'blue'], ['Health letter issued — see My Profile › Health Letters', '2026-10-21 09:30', 'Dr. Sarah Mitchell', 'green']] });
    b.letter.issued = 'HL-2041'; R.unshift(a, b);
    if (S.cases && !S.cases.some(c => c.reqId === 'rhl2')) S.cases.splice(1, 0, { id: 'IN-' + (1201 + S.cases.length), reqId: 'rhl2', letterReq: a.letter, title: fly.name, cat: 'Letter', pid: ME, who: null, match: 'linked', status: 'Under Review', type: 'Health letter — ' + fly.name, source: 'Platform', dept: 'GP’s', assigned: 'Sofia Sadiq', autoBy: 'Sofia Sadiq', closed: false, appt: null, submitted: '2026-10-22', updated: '3h ago', practitioner: 'Dr. Sarah Mitchell', candIdx: 0,
      desc: a.desc + '\nNeeded for: 1 month · From: 03/12/2026 · For: Airline or travel provider · Needed by: 25/11/2026\nPaid £' + Number(fly.price).toFixed(2) + ' online (' + flyInv + ').', docs: ['discharge-summary.pdf'], notes: [], chat: [], reqDocs: [], logs: [['Request submitted from patient portal', '22 Oct 2026, 09:55', 'Ahmed Raza'], ['Auto-assigned to Sofia Sadiq', '22 Oct 2026, 09:55', 'System']] });
  })();

  /* secure payment for paid letters */
  const PAY = App.ui.mrPay = { method: 'card', save: true };
  App.route('/me/requests/new/pay', () => { const l = L(), p = PT.pat(ME); if (!l || !l.paid) return App.go('#/me/requests/new') || '';
    return `<nav class="crumbs"><a href="#/me/requests">My Requests</a><span>/</span><a href="#/me/requests/new">New Request</a><span>/</span><span class="cur">Secure Payment</span></nav><div class="me-head"><h1>Secure Payment</h1><p>Pay for your health letter. Your request is sent to the clinic once payment is received.</p></div>
      <div class="me-pay"><section class="card card-pad stack g12"><div class="row g12"><span class="bl-dic"><i class="ri-lock-line"></i></span><div><b>Secure Payment</b><br><small class="caption">Your payment information is encrypted and secure</small></div></div><b class="sub2">Payment Method</b><div class="row g8">${[['card', 'Credit/Debit Card'], ['paypal', 'PayPal']].map(([k, t]) => `<button class="btn ${PAY.method === k ? 'primary' : 'outlined pt-dark'}" style="min-width:150px" data-act="mr-pm" data-v="${k}">${t}</button>`).join('')}</div>
        ${PAY.method === 'card' ? `<form class="stack g12" id="pt-form" onsubmit="return false">${PT.F('Card Number', 'cn', '', { req: true, ph: '1234 5678 9012 3456' })}${PT.F('Cardholder Name', 'ch', PT.name(p), { req: true })}<div class="g2">${PT.F('Expiry Date', 'ex', '', { req: true, ph: 'MM/YY' })}${PT.F('CVV', 'cvv', '', { req: true, ph: '123' })}</div></form><label class="cbx"><input type="checkbox" data-ch="mr-save" ${PAY.save ? 'checked' : ''}>Save card details for future payments</label>` : '<div class="pt-note"><i class="ri-paypal-line"></i>You’ll be taken to PayPal to approve the payment, then brought back here.</div>'}
        <div class="g2" style="gap:10px"><a class="btn outlined lg pt-dark" href="#/me/requests/new">Back</a><button class="btn primary lg" data-act="mr-pay">Pay ${money(l.price)} &amp; Submit</button></div><div class="pa-bar blue"><i class="ri-information-line"></i>Your payment is secured with 256-bit SSL encryption. We never store your full card details.</div></section>
      <aside class="card card-pad stack g12"><h2 class="dh2" style="font-size:20px">Request Summary</h2>${[['ri-mail-open-line', 'Health letter', l.name], ['ri-folder-line', 'Category', l.cat], ['ri-user-line', 'Patient', PT.name(p)], N.dur && ['ri-time-line', 'Needed for', N.dur], N.from && ['ri-calendar-line', 'Starting from', PT.dmy(N.from)], N.forWho && ['ri-building-line', 'Letter for', N.forWho], N.needBy && ['ri-calendar-check-line', 'Needed by', PT.dmy(N.needBy)]].filter(Boolean).map(([i, k, x]) => `<div class="me-bs"><i class="${i}"></i><div><small>${k}</small><b>${esc(x)}</b></div></div>`).join('')}
        <hr style="margin:4px 0"><div class="row between caption"><span>Letter fee</span><span>${money(l.price)}</span></div><div class="row between"><b>Total</b><b class="me-due" style="font-size:24px">${money(l.price)}</b></div><div class="me-free"><i class="ri-checkbox-circle-line"></i>If the clinic can’t issue this letter, you’ll get a full refund.</div></aside></div>`; }, meta);
  acts['mr-pm'] = el => { PAY.method = el.dataset.v; keep(); }; chs['mr-save'] = el => { PAY.save = el.checked; };
  acts['mr-pay'] = el => { const l = L(); if (PAY.method === 'card') { const d = PT.formData(), bad = []; if (!/^\d{16}$/.test((d.cn || '').replace(/\s/g, ''))) bad.push('cn'); if (!(d.ch || '').trim()) bad.push('ch'); if (!/^(0[1-9]|1[0-2])\/\d\d$/.test((d.ex || '').trim())) bad.push('ex'); if (!/^\d{3,4}$/.test((d.cvv || '').trim())) bad.push('cvv');
      App.$$('#pt-form .field').forEach(fl => { const n = fl.querySelector('[name]'); if (n) fl.classList.toggle('err', bad.includes(n.name)); }); if (bad.length) return App.snack(bad.includes('cn') ? 'Enter the 16-digit card number.' : 'Check the highlighted card details.', 'error'); }
    el.disabled = true; el.innerHTML = '<i class="ri-loader-4-line spin"></i>Processing…';
    setTimeout(() => { const inv = 'HC-' + (5300 + (S.inv2 || []).length); if (S.inv2) S.inv2.unshift({ id: inv, pid: ME, svc: l.name, kind: 'Service', amt: +l.price, status: 'Payment Complete', issued: new Date(), appt: new Date(), ref: 'Health letter', clin: 'LeafEase Clinic', method: PAY.method === 'card' ? 'Card' : 'PayPal', pays: [{ amt: +l.price, method: 'Card', at: new Date() }], log: [['Payment successfully made', new Date(), '']] }); submit(inv); }, 900); };
})();
